import sys


def classify_triangle(a: int, b: int, c: int) -> str:
    """返回三角形的类型；不能构成非退化三角形时返回 'Not a triangle!'。"""
    sides = sorted((a, b, c))
    # 非退化三角形：三边均 > 0，且任意两边之和 > 第三边。
    # 排好序后，只需检查一条不等式：sides[0] + sides[1] > sides[2]。
    # 理由：sides[0] + sides[2] > sides[1] 等价于 sides[0] + sides[2] > sides[2]
    # 一定成立（因为 sides[2] > sides[1] 且 sides[0] > 0），另一条同理。
    if sides[0] <= 0 or sides[0] + sides[1] <= sides[2]:
        return "Not a triangle!"
    # 分类一步到位：不同边长的个数就是相等关系的个数。
    kinds = len({sides[0], sides[1], sides[2]})
    if kinds == 1:
        return "Equilateral triangle!"
    if kinds == 2:
        return "Isosceles triangle!"
    return "Ordinary triangle!"


def main() -> None:
    data = sys.stdin.read().split()
    if len(data) < 3:
        return
    out = []
    # 按每 3 个一组处理：单组数据是它的退化成 1 组的形式。
    for i in range(0, len(data) - 2, 3):
        try:
            sides = [int(data[i]), int(data[i + 1]), int(data[i + 2])]
        except ValueError:
            # 极端异常输入（非整数 token）直接跳过，保证主流程不抛异常。
            continue
        out.append(classify_triangle(sides[0], sides[1], sides[2]))
    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()
